// LIMPIEZA Y VALIDACION
// 1. Trim de espacios  2. Deduplicacion por vacancy_id
// 3. Normalizacion de client_name  4. Fee '$1900 USD' -> 1900
// 5. Fechas MM/DD/YYYY -> YYYY-MM-DD  6. Reglas de negocio
const seen = new Set();
const out = [];

const fixDate = (s) => {
  if (!s) return null;
  const us = String(s).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (us) return `${us[3]}-${us[1]}-${us[2]}`;
  return s;
};

for (const item of $input.all()) {
  const r = { ...item.json };

  for (const k of Object.keys(r)) {
    if (typeof r[k] === 'string') r[k] = r[k].trim();
  }

  if (seen.has(r.vacancy_id)) continue; // duplicado exacto: fuera
  seen.add(r.vacancy_id);

  r.client_name = String(r.client_name || '')
    .toLowerCase()
    .replace(/\b\w/g, (c) => c.toUpperCase());

  if (r.monthly_fee_usd !== '' && r.monthly_fee_usd != null) {
    r.monthly_fee_usd = parseFloat(String(r.monthly_fee_usd).replace(/[^0-9.]/g, ''));
  } else {
    r.monthly_fee_usd = null;
  }

  r.opened_date = fixDate(r.opened_date);
  r.filled_date = fixDate(r.filled_date) || null;

  const issues = [];
  if (!r.recruiter_id) issues.push('recruiter_id faltante');
  if (r.status === 'Filled' && !r.filled_date) issues.push('Filled sin filled_date');
  if (r.status === 'Filled' && (r.monthly_fee_usd == null || isNaN(r.monthly_fee_usd))) issues.push('Filled sin fee valido');
  if (r.filled_date && r.opened_date && r.filled_date < r.opened_date) issues.push('filled_date anterior a opened_date');

  out.push({ json: { ...r, _valid: issues.length === 0, _issues: issues } });
}

return out;

// Solo registros validos, sin campos internos
return $input.all()
  .filter((i) => i.json._valid)
  .map((i) => {
    const { _valid, _issues, ...rest } = i.json;
    return { json: rest };
  });

// REPORTE DE CALIDAD + RECONCILIACION
// Compara filas de entrada vs salida: entrada = duplicados + validos + invalidos
const cleaned = $input.all().map((i) => i.json);
const rowsIn = $('Extraer CSV').all().length;
const valid = cleaned.filter((r) => r._valid);
const invalid = cleaned.filter((r) => !r._valid);

const issueCount = {};
for (const r of invalid) {
  for (const is of r._issues) issueCount[is] = (issueCount[is] || 0) + 1;
}

const revenue = valid
  .filter((r) => r.status === 'Filled')
  .reduce((s, r) => s + (r.monthly_fee_usd || 0), 0);

const duplicates = rowsIn - cleaned.length;
const reconciled = rowsIn === duplicates + valid.length + invalid.length;

return [{
  json: {
    executed_at: new Date().toISOString(),
    source_file: 'vacancies_raw.csv',
    rows_in: rowsIn,
    duplicates_removed: duplicates,
    rows_valid: valid.length,
    rows_invalid: invalid.length,
    reconciliation_check: reconciled ? 'OK' : 'MISMATCH',
    issues_breakdown: issueCount,
    total_monthly_revenue_usd: Math.round(revenue),
  },
}];
